    expect(items[0].textContent).toContain('Kategorie A');
    expect(items[0].textContent).toContain('32,00 €');
    expect(items[1].textContent).toContain('Reihe B, Platz 3');
    expect(items[1].textContent).toContain('Kategorie B');
