    [HttpPost("{reference}/cancel")]
    public async Task<ActionResult<BookingDto>> CancelBooking(string reference)
    {
        var result = await bookingService.CancelBookingAsync(reference);

        if (result.NotFound)
        {
            return NotFound();
        }

        if (result.AlreadyCancelled)
